src.main.loadMonaco.source_code:
async function loadMonaco() {
  if (!monacoInstance) {
    const monaco = await import("monaco-editor");
    monacoInstance = monaco;

    // Configure Mermaid language after Monaco is loaded
    const { configureMermaidLanguage } = await import("./configMermaidLanguage");
    configureMermaidLanguage(monaco);

    return monaco;
  }
  return monacoInstance;
}

src.main.setupModalDismiss.source_code:
function setupModalDismiss(
  modal: HTMLElement,
  trigger: HTMLElement,
  hiddenClass = "hidden",
): void {
  document.addEventListener("click", (e) => {
    if (
      !modal.contains(e.target as Node) &&
      !trigger.contains(e.target as Node) &&
      !modal.classList.contains(hiddenClass)
    ) {
      modal.classList.add(hiddenClass);
    }
  });
  document.addEventListener("keydown", (e) => {
    if (e.key === "Escape" && !modal.classList.contains(hiddenClass)) {
      modal.classList.add(hiddenClass);
    }
  });
}

