src.main.MermaidEditor.findFirstContentL.source_code:
private findFirstContentLine(lines: string[]): number | null {
    for (let i = 0; i < lines.length; i++) {
      const line = lines[i].trim();
      if (line && !line.startsWith("%%") && !line.startsWith("#")) {
        return i + 1;
      }
    }
    return null;
  }

